import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

interface SheetView {
  id: string;
  /** The sheet's today (YYYY-MM-DD): every date-dependent decision and default uses it. */
  today: string;
  /** Whether the sheet is archived: everything stays visible and every change is refused. */
  archived: boolean;
  /** The number of the sheet's last settle batch (a bulk settle that settled a claim); null while it
   *  has had none. */
  lastSettleBatch: number | null;
  /** The id of the sheet's parent, whose rates are used where it has none in force; null when none. */
  parent: string | null;
}

// Who is signed in and which sheet is active. Every request to the server carries the signed-in
// name in the X-User header (see `headers()`); everything else in the app is kept per sheet. While an
// as-of date is set, every request also carries it in the X-As-Of header: the server then shows each
// sheet as it stood at the end of that date (that date standing in for its today) and refuses every
// change. The as-of date belongs to this screen alone.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheetId = signal<string | null>(null);
  /** The active sheet's today (YYYY-MM-DD); use it, never the browser's clock. While an as-of date is
   *  set, it is that date. */
  readonly today = signal<string | null>(null);
  /** Whether the active sheet is archived. */
  readonly archived = signal(false);
  /** The number of the active sheet's last settle batch; null while it has had none. */
  readonly lastSettleBatch = signal<number | null>(null);
  /** The id of the active sheet's parent; null when it has none. */
  readonly parent = signal<string | null>(null);
  /** The date (YYYY-MM-DD) the sheets are shown as of; null when they are shown as they stand. */
  readonly asOf = signal<string | null>(null);
  /** Counts sheet loads, so a view re-reads the store even when the same id is loaded again. */
  readonly loads = signal(0);
  readonly signedIn = computed(() => this.user() !== null);

  signIn(name: string): boolean {
    const user = name.trim();
    if (!user) return false;
    this.user.set(user);
    this.sheetId.set(null);
    this.today.set(null);
    this.archived.set(false);
    this.lastSettleBatch.set(null);
    this.parent.set(null);
    this.asOf.set(null);
    return true;
  }

  headers(): HttpHeaders {
    const asOf = this.asOf();
    return new HttpHeaders(asOf ? { 'X-User': this.user() ?? '', 'X-As-Of': asOf } : { 'X-User': this.user() ?? '' });
  }

  /** Show the sheets as of a date (YYYY-MM-DD), re-reading the active one; resolves false when the
   *  date is not one. */
  async setAsOf(date: string): Promise<boolean> {
    const asOf = date.trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(asOf)) return false;
    this.asOf.set(asOf);
    const sheet = this.sheetId();
    return sheet ? this.loadSheet(sheet) : true;
  }

  /** Show the sheets as they stand again, re-reading the active one. */
  async clearAsOf(): Promise<boolean> {
    this.asOf.set(null);
    const sheet = this.sheetId();
    return sheet ? this.loadSheet(sheet) : true;
  }

  /** Load a sheet by id (starting it empty if never used); resolves false when refused. */
  async loadSheet(id: string): Promise<boolean> {
    const sheet = id.trim();
    if (!sheet || !this.user()) return false;
    try {
      const view = await firstValueFrom(
        this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(sheet)}/load`, null, {
          headers: this.headers(),
        }),
      );
      this.show(view);
      this.loads.update((n) => n + 1);
      return true;
    } catch {
      return false;
    }
  }

  /** Change the active sheet's today; resolves false when refused. */
  async setToday(date: string): Promise<boolean> {
    const sheet = this.sheetId();
    const today = date.trim();
    if (!sheet || !/^\d{4}-\d{2}-\d{2}$/.test(today)) return false;
    try {
      const view = await firstValueFrom(
        this.http.put<SheetView>(
          `/api/sheets/${encodeURIComponent(sheet)}/today`,
          { today },
          { headers: this.headers() },
        ),
      );
      if (this.sheetId() === view.id) this.show(view);
      return true;
    } catch {
      return false;
    }
  }

  /** Archive the active sheet; resolves false when refused. */
  async archive(): Promise<boolean> {
    const sheet = this.sheetId();
    if (!sheet) return false;
    try {
      const view = await firstValueFrom(
        this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(sheet)}/archive`, null, {
          headers: this.headers(),
        }),
      );
      if (this.sheetId() === view.id) this.show(view);
      return true;
    } catch {
      return false;
    }
  }

  /** Clone the active sheet to another id, one never used; resolves the clone's id, or null when refused. */
  async cloneSheet(to: string): Promise<string | null> {
    const sheet = this.sheetId();
    const target = to.trim();
    if (!sheet || !target) return null;
    try {
      const view = await firstValueFrom(
        this.http.post<SheetView>(
          `/api/sheets/${encodeURIComponent(sheet)}/clone`,
          { to: target },
          { headers: this.headers() },
        ),
      );
      return view.id;
    } catch {
      return null;
    }
  }

  private show(view: SheetView): void {
    this.sheetId.set(view.id);
    this.today.set(view.today);
    this.archived.set(view.archived);
    this.lastSettleBatch.set(view.lastSettleBatch);
    this.parent.set(view.parent ?? null);
  }
}
import { Component, inject, signal } from '@angular/core';
import { Session } from './session';

// Sign-in by name (no password), the signed-in name, and the sheet chooser with the active id.
@Component({
  selector: 'app-session-bar',
  template: `
    @if (session.user(); as user) {
      <section class="bar" aria-label="Session">
        <span
          >Signed in as <strong data-testid="current-user">{{ user }}</strong></span
        >
        <form (submit)="load($event)">
          <label for="sheet-id">Sheet</label>
          <input
            id="sheet-id"
            data-testid="sheet-id-input"
            [value]="sheetInput()"
            (input)="sheetInput.set(value($event)); sheetError.set(false)"
          />
          <button type="submit" data-testid="sheet-load">Load</button>
        </form>
        @if (session.sheetId(); as sheet) {
          <span
            >Sheet <strong data-testid="sheet-current-id">{{ sheet }}</strong></span
          >
          <span
            >Today <strong data-testid="sheet-today">{{ session.today() }}</strong></span
          >
          <form (submit)="saveToday($event)">
            <label for="sheet-today-input">Change today</label>
            <input
              id="sheet-today-input"
              type="date"
              data-testid="sheet-today-input"
              [value]="todayInput()"
              (input)="todayInput.set(value($event)); todayError.set(false)"
            />
            <button type="submit" data-testid="sheet-today-save">Set today</button>
          </form>
          <span
            >Archived
            <strong data-testid="sheet-archived">{{ session.archived() ? 'yes' : 'no' }}</strong></span
          >
          <span
            >Parent sheet <strong data-testid="sheet-parent">{{ session.parent() ?? '' }}</strong></span
          >
          <button type="button" data-testid="sheet-archive" (click)="archive()">
            Archive sheet
          </button>
          <form (submit)="cloneSheet($event)">
            <label for="sheet-clone-to">Clone to sheet</label>
            <input
              id="sheet-clone-to"
              data-testid="sheet-clone-to"
              [value]="cloneInput()"
              (input)="cloneInput.set(value($event)); cloneError.set(false)"
            />
            <button type="submit" data-testid="sheet-clone">Clone sheet</button>
          </form>
          <span
            >Cloned to <strong data-testid="sheet-cloned-to">{{ clonedTo() ?? '' }}</strong></span
          >
          <form (submit)="setAsOf($event)">
            <label for="asof-date">Show as of</label>
            <input
              id="asof-date"
              type="date"
              data-testid="asof-date"
              [value]="asOfInput()"
              (input)="asOfInput.set(value($event)); asOfError.set(false)"
            />
            <button type="submit" data-testid="asof-set">Set as of</button>
            <button type="button" data-testid="asof-clear" (click)="clearAsOf()">Clear as of</button>
          </form>
          <span
            >As of <strong data-testid="sheet-asof">{{ session.asOf() ?? '' }}</strong></span
          >
          @if (asOfError()) {
            <p role="alert" class="error" data-testid="asof-error">Type a date to show the sheet as of.</p>
          }
          @if (todayError()) {
            <p role="alert" class="error" data-testid="sheet-error">
              That date could not be set as today.
            </p>
          }
          @if (archiveError()) {
            <p role="alert" class="error" data-testid="sheet-error">
              The sheet could not be archived.
            </p>
          }
          @if (cloneError()) {
            <p role="alert" class="error" data-testid="sheet-error">
              The sheet could not be cloned to that sheet.
            </p>
          }
        }
        @if (sheetError()) {
          <p role="alert" class="error" data-testid="sheet-load-error">
            That sheet could not be loaded.
          </p>
        }
      </section>
    } @else {
      <form class="bar" (submit)="signIn($event)" aria-label="Sign in">
        <label for="signin-name">Your name</label>
        <input
          id="signin-name"
          data-testid="signin-name"
          [value]="nameInput()"
          (input)="nameInput.set(value($event)); signinError.set(false)"
        />
        <button type="submit" data-testid="signin-submit">Sign in</button>
        @if (signinError()) {
          <p role="alert" class="error" data-testid="signin-error">Type a name to sign in.</p>
        }
      </form>
    }
  `,
  styles: `
    .bar {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      align-items: center;
      padding: 0.5rem 0;
    }
    form {
      display: flex;
      gap: 0.5rem;
      align-items: center;
    }
    .error {
      color: #a40000;
      margin: 0;
    }
  `,
})
export class SessionBar {
  protected readonly session = inject(Session);
  protected readonly nameInput = signal('');
  protected readonly sheetInput = signal('');
  protected readonly signinError = signal(false);
  protected readonly sheetError = signal(false);
  protected readonly todayInput = signal('');
  protected readonly todayError = signal(false);
  protected readonly archiveError = signal(false);
  protected readonly cloneInput = signal('');
  protected readonly clonedTo = signal<string | null>(null);
  protected readonly cloneError = signal(false);
  protected readonly asOfInput = signal('');
  protected readonly asOfError = signal(false);

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  protected signIn(event: Event): void {
    event.preventDefault();
    this.signinError.set(!this.session.signIn(this.nameInput()));
  }

  protected async load(event: Event): Promise<void> {
    event.preventDefault();
    this.sheetError.set(false);
    this.todayError.set(false);
    this.archiveError.set(false);
    this.cloneError.set(false);
    this.sheetError.set(!(await this.session.loadSheet(this.sheetInput())));
  }

  protected async saveToday(event: Event): Promise<void> {
    event.preventDefault();
    this.todayError.set(false);
    this.archiveError.set(false);
    this.cloneError.set(false);
    this.todayError.set(!(await this.session.setToday(this.todayInput())));
  }

  protected async setAsOf(event: Event): Promise<void> {
    event.preventDefault();
